 60→// handleLifecycleSessionStart handles session start: shows banner, checks concurrent sessions,
 61→// fires state machine transition.
 62→func handleLifecycleSessionStart(ctx context.Context, ag agent.Agent, event *agent.Event) error {
 63→	logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
