168→// ensures strategy setup, initializes session.
169→func handleLifecycleTurnStart(ctx context.Context, ag agent.Agent, event *agent.Event) error {
170→	logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
171→	logging.Info(logCtx, "turn-start",
172→		slog.String("event", event.Type.String()),
173→		slog.String("session_id", event.SessionID),
174→		slog.String("session_ref", event.SessionRef),
175→		slog.String("model", event.Model),
176→	)
177→
178→	sessionID := event.SessionID
179→	if sessionID == "" {
180→		return fmt.Errorf("no session_id in %s event", event.Type)
181→	}
182→	if err := validation.ValidateSessionID(sessionID); err != nil {
183→		return fmt.Errorf("invalid %s event: %w", event.Type, err)
184→	}
185→
186→	// Fill model from hint file if the agent didn't provide it on this hook
187→	if event.Model == "" {
188→		if hint := strategy.LoadModelHint(ctx, sessionID); hint != "" {
189→			event.Model = hint
190→			logging.Debug(logCtx, "loaded model from hint file",
191→				slog.String("model", hint))
192→		}
193→	}
194→
