196→	if err := CapturePrePromptState(ctx, ag, sessionID, event.SessionRef); err != nil {
197→		return err
198→	}
199→
200→	// Append prompt to prompt.txt on filesystem so it's available for
201→	// mid-turn commits (before SaveStep writes it to the shadow branch).
202→	// Prompts are separated by "\n\n---\n\n" to support multiple turns.
203→	if event.Prompt != "" {
204→		sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
205→		if sessionDirAbs, absErr := paths.AbsPath(ctx, sessionDir); absErr == nil {
206→			if mkErr := os.MkdirAll(sessionDirAbs, 0o750); mkErr == nil {
207→				promptPath := filepath.Join(sessionDirAbs, paths.PromptFileName)
208→				existing, readErr := os.ReadFile(promptPath) //nolint:gosec // session metadata path
209→				var content string
210→				if readErr == nil && len(existing) > 0 {
211→					content = string(existing) + "\n\n---\n\n" + event.Prompt
212→				} else {
213→					content = event.Prompt
214→				}
215→				if writeErr := os.WriteFile(promptPath, []byte(content), 0o600); writeErr != nil {
216→					logging.Warn(logCtx, "failed to write prompt.txt",
217→						slog.String("error", writeErr.Error()))
218→				}
219→			}
220→		}
221→	}
222→
223→	// Ensure strategy setup and initialize session
224→	if err := strategy.EnsureSetup(ctx); err != nil {
225→		logging.Warn(logCtx, "failed to ensure strategy setup",
226→			slog.String("error", err.Error()))
227→	}
228→
229→	strat := GetStrategy(ctx)
230→	if err := strat.InitializeSession(ctx, sessionID, ag.Type(), event.SessionRef, event.Prompt, event.Model); err != nil {
231→		logging.Warn(logCtx, "failed to initialize session state",
232→			slog.String("error", err.Error()))
233→	}
234→
235→	return nil
236→}
